// Per-race highlights for the home page. Generated by scripts/highlights/race_highlights.py
// (FastF1, official F1 timing) or race_from_export.py (a FastF1 export of the weekend's Q and R),
// or, for a past edition's pole lap and track map only, by
// scripts/highlights/openf1_pole_lap.py (OpenF1) — never hand-edited. Each block carries its own
// `source`; a race without a file, or a file missing a block, hides that module instead of
// showing a stale number.
// Practice sessions of the coming race come from scripts/highlights/practice_from_export.py
// (a FastF1 export of one session), one file per session.
// Static imports (not fs) so this works on the Cloudflare Worker runtime too: add one line per race.
import r2025_19 from '@/content/race-highlights/2025-19.json';
import r2026_17 from '@/content/race-highlights/2026-17.json';
import r2026_18 from '@/content/race-highlights/2026-18.json';
import p2026_18_fp2 from '@/content/race-highlights/2026-18-fp2.json';
import p2026_18_fp3 from '@/content/race-highlights/2026-18-fp3.json';
import p2026_18_q from '@/content/race-highlights/2026-18-q.json';
import p2026_19_fp2 from '@/content/race-highlights/2026-19-fp2.json';

export type PoleLap = {
  driver: string;
  lapTime: string;
  speedKmh: number[];
  topSpeedKmh: number;
  minSpeedKmh: number;
  source: string;
};

export type TrackMap = {
  width: number;
  height: number;
  points: [number, number, number][];
  topSpeedAt: [number, number];
  minSpeedAt: [number, number];
  source: string;
};

export type DuelDriver = {
  driver: string;
  lapTime: string;
  sectors: [number, number, number];
  teamColour: string | null;
};

export type PoleDuel = {
  pole: DuelDriver;
  challenger: DuelDriver;
  source: string;
};

export type LapsLed = {
  driver: string;
  laps: number;
  totalLaps: number;
  source: string;
};

export type TraceDriver = {
  driver: string;
  team: string;
  teamColour: string | null;
  positions: (number | null)[];
  pitLaps: number[];
};

export type RaceTrace = {
  totalLaps: number;
  drivers: TraceDriver[];
  // Only present when the flag lap reproduces the official classification interval.
  gap?: { leader: string; chaser: string; seconds: number[] };
  vscLaps: number[];
  scLaps: number[];
  source: string;
};

export type DominanceSection = {
  faster: string;
  gain: number;
  corners: string[];
  path: [number, number][];
};

export type QualiDominance = {
  pole: { driver: string; lapTime: string; teamColour: string | null };
  challenger: { driver: string; lapTime: string; teamColour: string | null };
  width: number;
  height: number;
  lapLength: number;
  sectorEnds: [number, number];
  boundaries: number[];
  // challenger's elapsed time minus the pole-sitter's at each boundary: > 0 = pole-sitter ahead.
  gapAtBoundaries: number[];
  sections: DominanceSection[];
  corners: Array<{ number: string; at: [number, number]; distance: number }>;
  source: string;
};

export type RaceHighlights = {
  year: number;
  round: number;
  event: string;
  poleLap?: PoleLap;
  trackMap?: TrackMap;
  poleDuel?: PoleDuel;
  qualiDominance?: QualiDominance;
  lapsLed?: LapsLed;
  raceTrace?: RaceTrace;
};

const REGISTRY: Record<string, RaceHighlights> = {
  // JSON imports widen tuples to number[][]; the generator script guarantees the shape.
  '2025-19': r2025_19 as unknown as RaceHighlights,
  '2026-17': r2026_17 as unknown as RaceHighlights,
  '2026-18': r2026_18 as unknown as RaceHighlights,
};

export function getRaceHighlightsFor(year: number, round: number): RaceHighlights | null {
  return REGISTRY[`${year}-${round}`] ?? null;
}

export type PracticeFastestLap = PoleLap & { team: string; compound: string };

export type LongRun = {
  driver: string;
  team: string;
  teamColour: string | null;
  compound: string;
  laps: number;
  deletedLaps: number;
  meanSeconds: number;
  degPerLap: number;
  tyreLife: [number, number];
};

// Height of one lap in metres above its own lowest point (FastF1 Z), evenly spaced by distance.
export type ElevationProfile = {
  driver: string;
  lapLength: number;
  heightM: number[];
  corners: Array<{ number: string; distance: number }>;
  source: string;
};

export type PracticeHighlights = {
  year: number;
  round: number;
  event: string;
  session: 'FP1' | 'FP2' | 'FP3' | 'Q';
  fastestLap?: PracticeFastestLap;
  trackMap?: TrackMap;
  elevation?: ElevationProfile;
  longRuns?: { runs: LongRun[]; minLaps: number; slowLapPct: number; source: string };
};

// One race's practice and qualifying files, in session order.
const PRACTICE: Record<string, PracticeHighlights[]> = {
  '2026-18': [p2026_18_fp2 as unknown as PracticeHighlights, p2026_18_fp3 as unknown as PracticeHighlights, p2026_18_q as unknown as PracticeHighlights],
  '2026-19': [p2026_19_fp2 as unknown as PracticeHighlights],
};

/** The race's latest practice session with a file, or null. */
export function getLatestPracticeFor(year: number, round: number): PracticeHighlights | null {
  return PRACTICE[`${year}-${round}`]?.at(-1) ?? null;
}

/** The race's practice session with the most long runs: the one teams used for race simulations. */
export function getLongRunPracticeFor(year: number, round: number): PracticeHighlights | null {
  const sessions = (PRACTICE[`${year}-${round}`] ?? []).filter((s) => s.longRuns?.runs.length);
  return sessions.reduce<PracticeHighlights | null>((best, s) => (!best || s.longRuns!.runs.length > best.longRuns!.runs.length ? s : best), null);
}

// FastF1 team names -> Supabase constructor_ref, for the team colour tokens.
export const FASTF1_TEAM_REF: Record<string, string> = {
  McLaren: 'mclaren',
  'Red Bull Racing': 'red_bull',
  Ferrari: 'ferrari',
  Mercedes: 'mercedes',
  Alpine: 'alpine',
  'Racing Bulls': 'rb',
  Audi: 'audi',
  'Aston Martin': 'aston_martin',
  'Haas F1 Team': 'haas',
  Williams: 'williams',
  Cadillac: 'cadillac',
};
